import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r}from"./chunks/M-S-HDS-WF-Scr.ATovYKe5.js";import{_ as i,o as a,c as t,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Follower Web Libre","description":"","frontmatter":{"source_hash":"8c757f2bd2","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/webfollow.md","filePath":"it/troubleshoot/webfollow.md"}'),s={name:"it/troubleshoot/webfollow.md"};function n(p,e,d,c,u,m){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="libre-web-follower" tabindex="-1">Libre Web Follower <a class="header-anchor" href="#libre-web-follower" aria-label="Permalink to &quot;Libre Web Follower {#libre-web-follower}&quot;">​</a></h1><h2 id="system-setup" tabindex="-1">Configurazione del sistema <a class="header-anchor" href="#system-setup" aria-label="Permalink to &quot;Configurazione del sistema {#system-setup}&quot;">​</a></h2><p>Quando usi questa sorgente dati devi assicurarti che il sistema sia configurato correttamente con le app del produttore.</p><p><strong>L&#39;app master (collegata al sensore Libre) deve caricare i dati sul <a href="https://www.libreview.com/" target="_blank" rel="noreferrer">server</a> del produttore.</strong></p><p>Esci ed entra di nuovo nel server per verificare di usare le credenziali giuste.</p><p>Assicurati che sul server ci siano dati.</p><p><strong>L&#39;app <a href="https://play.google.com/store/search?q=librelinkup&amp;c=apps" target="_blank" rel="noreferrer">follower</a> del produttore deve ricevere i dati condivisi.</strong></p><p>Prova a eliminare e inviare di nuovo un invito all&#39;app follower del produttore (usando l&#39;app master del produttore).</p><p>Prova a disinstallare e reinstallare l&#39;app follower del produttore.</p><ul><li>Per accedere usa preferibilmente le credenziali dell&#39;invito.</li><li>Se non funziona, usa le credenziali dell&#39;app master (server) e invia di nuovo l&#39;invito.</li></ul><br><h2 id="xdrip-setup" tabindex="-1">Configurazione di xDrip <a class="header-anchor" href="#xdrip-setup" aria-label="Permalink to &quot;Configurazione di xDrip {#xdrip-setup}&quot;">​</a></h2><p>Quando il sistema funziona con le app del produttore, puoi passare alla risoluzione dei problemi di xDrip.</p><ol><li>Assicurati che la sorgente dati sia <a href="./../install/webfollower.html">Web follower</a>.</li><li>Usa le credenziali del follower che hai invitato con l&#39;app master del produttore.</li><li>Se non funziona, puoi provare a usare le credenziali del server per individuare il problema, ma fai attenzione a ridurre il rischio di blocco dell&#39;account.</li></ol><br><h2 id="vendor-servers-updates" tabindex="-1">Aggiornamenti dei server del produttore <a class="header-anchor" href="#vendor-servers-updates" aria-label="Permalink to &quot;Aggiornamenti dei server del produttore {#vendor-servers-updates}&quot;">​</a></h2><p>Gli aggiornamenti del server possono rompere il meccanismo.</p><p><strong>Una volta che xDrip è stato corretto</strong>, potresti doverlo reimpostare seguendo questa sequenza:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Web Follower</p></div><p>Modifica il <code>Configuration script</code></p><div class="admonition xdripitem"><p class="admonition-title">Configuration Script</p><p> This is the community helper address or keyword</p></div><p>Aggiungi uno spazio dopo <code>beonlabs</code> e seleziona <code>Ok</code></p><img src="'+r+'" style="zoom:75%;"><p>Modifica di nuovo il <code>Configuration script</code>, <strong>togli lo spazio</strong> dopo <code>beonlabs</code> e seleziona <code>Ok</code>.</p><p>Aspetta fino a un minuto che i dati vengano di nuovo visualizzati.</p><br><p>Se il problema persiste, installa l&#39;app follower del produttore sullo stesso telefono e verifica che riceva i dati con le stesse credenziali.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 8/12/2024</em></a></p>',29)])])}const g=i(s,[["render",n]]);export{v as __pageData,g as default};
